 if(action==='resume-subject'){const s=selectedSubject();if(!s?.lessons.length){showToast('ابتدا درسی اضافه کن.');return}const completed=state.subjectProgress[s.id]||[];const last=s.lessons.find(l=>l.id===state.subjectLastPlace[s.id]),candidate=last||s.lessons.find((l,i)=>(i===0||completed.includes(s.lessons[i-1].id))&&!completed.includes(l.id))||s.lessons[0],idx=s.lessons.indexOf(candidate);activeSubjectLesson=idx===0||completed.includes(s.lessons[idx-1].id)?candidate.id:s.lessons.find((l,i)=>i===0||completed.includes(s.lessons[i-1].id)).id;state.subjectLastPlace[s.id]=activeSubjectLesson;save();navigate('subjectLesson');return}
 if(action==='new-subject-lesson'){lessonModal();return}
 if(action==='edit-subject-lesson'){const l=selectedSubject()?.lessons.find(l=>l.id===el.dataset.id);if(l)lessonModal(l);return}
 if(action==='delete-subject-lesson'){const s=selectedSubject(),l=s?.lessons.find(l=>l.id===el.dataset.id);if(l&&confirm('این درس حذف شود؟ تأیید و قفل مراحل با ترتیب جدید محاسبه خواهد شد.')){s.lessons=s.lessons.filter(x=>x.id!==l.id);state.subjectProgress[s.id]=(state.subjectProgress[s.id]||[]).filter(id=>id!==l.id);save();render()}return}
 if(action==='open-subject-lesson'){const s=selectedSubject(),id=el.dataset.id,idx=s?.lessons.findIndex(l=>l.id===id);if(idx<0)return;if(idx>0&&!(state.subjectProgress[s.id]||[]).includes(s.lessons[idx-1].id)){showToast('اول باید درس پیش‌نیاز تأیید شود.');return}activeSubjectLesson=id;state.subjectLastPlace[s.id]=id;save();navigate('subjectLesson');return}
 if(action==='subject-step'){const key=activeSubject+'|'+activeSubjectLesson,steps=(activeCustomLesson()?.steps||'').split('\n').filter(s=>s.trim());const d=state.subjectDrafts[key]||{};d.step=clamp(Number(d.step||0)+Number(el.dataset.direction),0,Math.max(0,steps.length-1));state.subjectDrafts[key]=d;save();render();return}
 if(action==='restore-layout'){if(confirm('فقط چیدمان کارت‌های داشبورد به پیش‌فرض برگردد؟')){state.workspace.cards=[...EXT_DEFAULTS.cards];state.workspace.hidden=[];save();render()}return}
 if(action==='move-card'){let a=state.workspace.cards,i=a.indexOf(el.dataset.id),j=i+Number(el.dataset.direction);if(j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];save();render()}return}
