document.addEventListener('change',e=>{const el=e.target,action=el.dataset.action;
 if(el.id==='library-picker'){uploadFiles(el);return}
 if(action==='setting-theme'){state.settings.theme=el.value;save();updateAppearance();return}
 if(action==='setting-font'){state.settings.fontScale=Number(el.value)/100;save();updateAppearance();const p=$('#font-percent');if(p)p.textContent=el.value+'٪';return}
 if(action==='setting-accent'){state.settings.accent=el.value;save();updateAppearance();return}
 if(action==='card-visibility'){const hidden=state.workspace.hidden;state.workspace.hidden=el.checked?hidden.filter(id=>id!==el.dataset.id):[...new Set([...hidden,el.dataset.id])];save();return}
});
document.addEventListener('input',e=>{const el=e.target,action=el.dataset.action;
 if(action==='setting-font'){state.settings.fontScale=Number(el.value)/100;save();updateAppearance();const p=$('#font-percent');if(p)p.textContent=el.value+'٪'}
 if(action==='workspace-nickname'){state.workspace.nickname=el.value;save()}
 if(action==='workspace-focus'){state.workspace.focus=el.value;save()}
 if(action==='subject-note'){state.subjectNotes[activeSubject+'|'+activeSubjectLesson]=el.value;save()}
 const form=el.closest('[data-form="subject-assessment"]');if(form&&el.name){const key=activeSubject+'|'+activeSubjectLesson;state.subjectDrafts[key]={...(state.subjectDrafts[key]||{}),[el.name]:el.type==='checkbox'?el.checked:el.value};save()}
});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;const type=form.dataset.form;if(!['flashcard','subject','subject-lesson','subject-assessment'].includes(type))return;e.preventDefault();const fd=new FormData(form);
 if(type==='flashcard'){const front=String(fd.get('front')||'').trim(),back=String(fd.get('back')||'').trim(),topic=String(fd.get('topic')||'').trim();if(!front||!back){showToast('دو طرف کارت باید تکمیل شوند.');return}let c=state.flashcards.find(c=>c.id===form.dataset.id);if(c)Object.assign(c,{front,back,topic});else state.flashcards.push({id:uid(),front,back,topic,box:1,dueAt:today(),createdAt:isoNow(),history:[]});save();closeModal();render();showToast('کارت در جعبهٔ لایتنر ذخیره شد.');return}
 if(type==='subject'){const title=String(fd.get('title')||'').trim();if(!title){showToast('نام علم ضروری است.');return}const data={title,description:String(fd.get('description')||'').trim(),goal:String(fd.get('goal')||'').trim()};let s=state.subjects.find(s=>s.id===form.dataset.id);if(s)Object.assign(s,data);else{const id=uid();state.subjects.push({id,...data,lessons:[],createdAt:isoNow()});activeSubject=id}save();closeModal();navigate('sciences');showToast('علم جدید در نقشهٔ شخصی ذخیره شد.');return}
 if(type==='subject-lesson'){const title=String(fd.get('title')||'').trim(),exercise=String(fd.get('exercise')||'').trim(),s=selectedSubject();if(!s||!title||!exercise){showToast('عنوان و تمرین لازم است.');return}const obj={title,goal:String(fd.get('goal')||'').trim(),concept:String(fd.get('concept')||'').trim(),steps:String(fd.get('steps')||'').trim(),example:String(fd.get('example')||'').trim(),exercise,expected:String(fd.get('expected')||'').trim()};const old=s.lessons.find(x=>x.id===form.dataset.id);if(old)Object.assign(old,obj);else s.lessons.push({id:uid(),...obj});save();closeModal();render();showToast('درس ذخیره شد و در نقشه قرار گرفت.');return}
 if(type==='subject-assessment'){const s=selectedSubject(),l=activeCustomLesson();if(!s||!l)return;const answer=String(fd.get('answer')||'').trim(),causal=String(fd.get('causal')||'').trim(),minutes=Number(fd.get('minutes'));if(!answer||causal.length<20||!Number.isInteger(minutes)||minutes<1||minutes>240){showToast('پاسخ، توضیح ۲۰ نویسه‌ای و زمان معتبر لازم است.');return}const pass=l.expected?norm(answer)===norm(l.expected):fd.get('selfVerified')==='1';const key=s.id+'|'+l.id;const prev=state.subjectDrafts[key]||{};state.subjectDrafts[key]={...prev,answer,causal,minutes,passed:pass,feedback:pass?(l.expected?'پاسخ با کلید ثبت‌شده مطابقت داشت؛ مرحله تأیید شد.':'مرحله بر اساس تأیید شخصی تو ثبت شد؛ راستی‌آزمایی خودکار انجام نشده است.'):'پاسخ دقیقاً با کلید کوتاه مطابقت ندارد؛ پاسخ یا کلید را بررسی و دوباره تلاش کن.'};if(pass){state.subjectProgress[s.id]=state.subjectProgress[s.id]||[];if(!state.subjectProgress[s.id].includes(l.id))state.subjectProgress[s.id].push(l.id)}state.sessions.push({id:uid(),track:'science',subjectId:s.id,lessonId:l.id,kind:'ارزیابی درس شخصی',title:s.title+' — '+l.title,minutes,date:today(),timestamp:isoNow(),passed:pass,score:pass?1:0,causal,note:answer});save();render();showToast(pass?'ارزیابی ثبت شد؛ درس بعدی باز شد.':'پاسخ نیازمند بازبینی است.');return}
});
window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(state.settings.theme==='system')updateAppearance()});
