function provisionalNodes(w){const c=classifySubject(w.title);if(!c)return [];
 return c.path.map((title,i)=>({id:uid(),title,goal:'پیش‌نیاز بنیادین «'+w.title+'» · مرحلهٔ '+(i+1),concept:'',steps:'',example:'',exercise:'',expected:'',quiz:[],cards:[],sources:[],verified:false,level:i+1,stage:'provisional'}));
}
function sourceLink(s){let url=typeof s==='string'?s:s?.url||'',h=safeHref(url),label=typeof s==='object'?(s.title||url):url;return h?`<a href="${cleanText(h)}" target="_blank" rel="noopener noreferrer">${cleanText(label.slice(0,90))}</a>`:cleanText(label.slice(0,90))}
function auditSubject(s){const warnings=[];if(!s.onboarding)warnings.push('پرسش‌های تعیین هدف و سطح این علم ثبت نشده‌اند.');if(!s.lessons?.length)warnings.push('زنجیرهٔ پیش‌نیازها هنوز تهیه نشده است.');
 s.lessons?.forEach((l,i)=>{if(!l.concept)warnings.push('درس «'+l.title+'»: متن تدریس تأییدشده ندارد.');if(!Array.isArray(l.quiz)||l.quiz.length!==5)warnings.push('درس «'+l.title+'»: پنج زاویهٔ ارزیابی کامل نیست.');if(!Array.isArray(l.sources)||!l.sources.length)warnings.push('درس «'+l.title+'»: منبع قابل بررسی ندارد.');if(i>0&&Array.isArray(l.prerequisites)){for(const p of l.prerequisites){if(!s.lessons.slice(0,i).some(x=>norm(x.title)===norm(p)))warnings.push('درس «'+l.title+'»: پیش‌نیاز «'+p+'» در مراحل قبلی دیده نمی‌شود.')}}});return warnings}
function renderScienceOnboard(s){const c=classifySubject(s.title),ob=s.onboarding||{},warn=auditSubject(s);return `<div class="card science-summary"><div class="card-title"><h3>مشخصات برنامهٔ اختصاصی</h3>${badge(s.planStatus==='researched'?'طرح AI؛ نیازمند تأیید منابع':s.planStatus==='provisional'?'نقشهٔ آفلاینِ پیشنهادی':'ساخت دستی',s.planStatus==='researched'?'green':'amber')}</div><div class="science-facts"><div><strong>هدف</strong><span>${cleanText(ob.goal||s.goal||'ثبت نشده')}</span></div><div><strong>سطح اولیه</strong><span>${cleanText(ob.prior||'نامشخص')}</span></div><div><strong>زمان روزانه</strong><span>${Number(ob.daily)||30} دقیقه</span></div><div><strong>روش</strong><span>${cleanText(ob.experiments||'شبیه‌سازی چرایی و چگونگی')}</span></div></div><div class="notice ${warn.length?'warning':'success'}">${warn.length?`${warn.length} مورد برای کنترل کامل پیش‌نیاز و اعتبار علمی باقی است. فهرست کامل را ببین.`:'ساختار پایه بررسی شد؛ کامل‌بودن تمام دانش یک علم به‌طور مطلق قابل تضمین نیست.'}</div><details><summary>ممیزی پوشش پایه‌ها و منابع (${warn.length})</summary><div class="audit-list">${warn.length?warn.map(x=>`<div>• ${cleanText(x)}</div>`).join(''):'مورد ساختاریِ ناقص پیدا نشد.'}</div></details><div class="form-actions"><button class="button button-primary" data-action="ai-build-plan" ${planBusy?'disabled':''}>${planBusy?'در حال بررسی منابع...':'◉ ساخت نقشهٔ مستند با AI آنلاین'}</button><button class="button button-outline" data-action="export-ai-prompt">دریافت دستور پژوهش دقیق</button><button class="button button-outline" data-action="import-plan-json">ورود برنامهٔ JSON تأییدشده</button><button class="button button-outline" data-action="wizard-edit">ویرایش پاسخ‌های تعیین سطح</button></div><p class="small muted">طرح مستند به اتصال اینترنت و کلید API در سرور محلی نیاز دارد؛ متن‌های آفلاین به‌عنوان محتوای علمیِ راستی‌آزمایی‌شده معرفی نمی‌شوند.</p></div>`;}
const oldRenderSciences=renderSciences;
renderSciences=function(){return oldRenderSciences().replace('رشته یا علم جدید، درس‌های مرحله‌ای، مثال، شبیه‌سازی پویای چرایی و چگونگی و تمرین اختصاصی را بدون تغییر کد اضافه کن. عبور از هر درس فقط پس از ثبت ارزیابی مجاز است.','برای هر علم ابتدا پرسش‌وپاسخ تعیین هدف، پیش‌نیاز و سطح آغاز می‌شود. بعد مسیر مرحله‌ایِ بنیادی شکل می‌گیرد؛ عبور از هر پله به پنج ارزیابی وابسته است.').replaceAll('افزودن علم','شروع گفت‌وگوی افزودن علم')};
const oldRenderSubject=renderSubject;
renderSubject=function(){const s=selectedSubject();return s?renderScienceOnboard(s)+oldRenderSubject():oldRenderSubject()};
function quizReady(l){return !!l.concept&&!!l.example&&Array.isArray(l.quiz)&&l.quiz.length===5&&l.quiz.every(q=>q.q&&q.answer)}
function renderV3Lesson(){const s=selectedSubject(),l=activeCustomLesson();if(!s||!l)return '<div class="notice warning">درس موجود نیست.</div>';const i=s.lessons.findIndex(x=>x.id===l.id),progress=state.subjectProgress[s.id]||[],done=progress.includes(l.id);if(i>0&&!progress.includes(s.lessons[i-1].id))return '<div class="notice warning">ابتدا پیش‌نیاز قبلی را کامل کن.</div>';
 const key=s.id+'|'+l.id,d=state.subjectDrafts[key]||{},steps=(l.steps||'').split('\n').map(x=>x.trim()).filter(Boolean),stage=clamp(Number(d.step)||0,0,Math.max(0,steps.length-1)),can=quizReady(l);
 return `<div class="crumb"><button data-action="open-subject" data-id="${cleanText(s.id)}">${cleanText(s.title)}</button> ‹ ${cleanText(l.title)}</div><section class="lesson-header"><div>${badge(done?'پله +۱ آزاد شده':can?'آمادهٔ سنجش پنج‌گانه':'نیازمند تولید و تأیید محتوا',done?'green':'amber')}<h2>${cleanText(l.title)}</h2><p>${cleanText(l.goal||'فهم بنیادی و درونی مفهوم')}</p></div><button class="button button-outline" data-action="open-subject" data-id="${cleanText(s.id)}">بازگشت به نقشه</button></section>
 <div class="grid-main"><section class="card"><h3>۱. تدریس از بنیادی‌ترین مفهوم</h3>${l.concept?`<p>${nl(l.concept)}</p>`:'<div class="notice warning">این درس هنوز متن آموزش معتبر ندارد. از AI آنلاین برای تهیهٔ محتوای مستند استفاده کن یا خودت آن را با منبع تأییدشده تکمیل کن.</div>'}<h4>شبیه‌سازی پویای چرایی و چگونگی</h4><div class="machine-subject"><div class="small muted">وضعیت ${stage+1} از ${steps.length||1}</div><strong>${cleanText(steps[stage]||'گام‌های شبیه‌سازی هنوز ثبت نشده‌اند.')}</strong></div><div class="form-actions"><button class="button button-outline" data-action="subject-step" data-direction="-1" ${stage===0?'disabled':''}>مرحلهٔ قبل</button><button class="button button-primary" data-action="subject-step" data-direction="1" ${stage>=steps.length-1?'disabled':''}>مرحلهٔ بعد</button></div><h4>۲. مثال حل‌شده و سؤال‌وجواب گام‌به‌گام</h4><div class="muted-box note-text">${nl(l.example||'مثال در انتظار تولید و تأیید')}</div><div class="notice">بعد از فهم سناریو، هر پنج زاویهٔ سؤال را پاسخ بده؛ پاسخ درستِ کوتاه کافی نیست، توضیح چرایی هم ضروری است.</div><div class="form-actions"><button class="button button-primary" data-action="ai-build-lesson" ${lessonBusy?'disabled':''}>${lessonBusy?'در حال ساخت...':'تهیهٔ درس و پنج سؤال با AI آنلاین'}</button><button class="button button-outline" data-action="edit-subject-lesson" data-id="${cleanText(l.id)}">ویرایش تدریس و سؤالات</button></div><h4>منابع و زمان بررسی</h4>${l.sources?.length?`<div class="source-list">${l.sources.map(x=>`<p>• ${sourceLink(x)}</p>`).join('')}</div>`:'<div class="small muted">منبع ثبت نشده؛ ادعای به‌روز بودن این درس تأیید نشده است.</div>'}<p class="small muted">${l.checkedAt?'آخرین تولید/بررسی: '+faDate(l.checkedAt):'تاریخ بررسی اینترنتی: نامعلوم'} · ${l.verified?'تهیه‌شده با AI؛ نیازمند کنترل انسانی':'بررسی علمی کامل نشده'}</p></section>
 <section class="card"><h3>۳. سنجش پنج‌زاویه‌ای (از آسان تا دشوار)</h3>${can?`<form data-form="v3-quiz" data-key="${cleanText(key)}"><div class="quiz-sections">${l.quiz.map((q,ix)=>`<div class="quiz-question"><strong>سؤال ${ix+1} — ${cleanText(q.axis||AXES[ix])}</strong><p>${nl(q.q)}</p><label class="form-label">پاسخ کوتاه</label><input class="field" name="a${ix}" value="${cleanText(d['a'+ix]||'')}" required maxlength="600"><label class="form-label">چرا؟ توضیح چرایی و چگونگی</label><textarea class="textarea" name="r${ix}" rows="2" minlength="12" required placeholder="دلیل را با کلمات خودت توضیح بده">${cleanText(d['r'+ix]||'')}</textarea>${d.results?.[ix]?`<div class="notice ${d.results[ix].ok?'success':'warning'}">${cleanText(d.results[ix].message)}${q.why?' · نکتهٔ علمی: '+cleanText(q.why):''}</div>`:''}</div>`).join('')}</div><label class="form-label">آموزش معکوس: درس را به زبان خودت برای یک مبتدی توضیح بده (حداقل ۹۰ نویسه)</label><textarea class="textarea" name="teachBack" minlength="90" rows="4" required>${cleanText(d.teachBack||'')}</textarea><label class="form-label">زمان واقعی مطالعه (دقیقه)</label><input class="field" name="minutes" type="number" min="1" max="180" value="${Number(d.minutes)||20}" required><label class="choice"><input type="checkbox" name="verifiedReasoning" required ${d.verifiedReasoning?'checked':''}> من توضیح‌هایم را با متن درس یا منابع مقایسه کرده‌ام و از صحتشان مطمئنم.</label><div class="form-actions"><button class="button button-primary" type="submit">بررسی پنج سؤال و ثبت نتیجه</button></div></form>`:'<div class="notice warning">آزمون پنج‌سؤالی این درس آماده نیست؛ بدون آن مرحلهٔ بعدی قفل می‌ماند. ثبت یک پاسخ یا خودارزیابیِ ساده دیگر کافی نیست.</div>'}
 ${d.feedback?`<div class="notice ${d.passed?'success':'warning'}">${cleanText(d.feedback)}</div>`:''}${done?`<div class="notice success">پنج محور پاسخ داده شده‌اند. ${l.cards?.length?'فلش‌کارت‌های همین مفهوم به جعبهٔ لایتنر افزوده شدند.':'می‌توانی برای مرور کارت‌های این درس را بسازی.'}</div>`:''}<h3>یادداشت و بازاندیشی</h3><textarea class="textarea" rows="5" data-action="subject-note" placeholder="مدل ذهنی، سؤال‌های جدید، خطاها ...">${cleanText(state.subjectNotes[key]||'')}</textarea></section></div>`;
}
renderSubjectLesson=renderV3Lesson;
function renderQuizEditor(l){const quiz=Array.isArray(l?.quiz)?l.quiz:[];return `<div class="editor-quiz"><h4>پنج سؤال مستقل؛ هر کدام با جواب دقیق و چرایی</h4>${AXES.map((axis,i)=>`<fieldset class="quiz-edit-row"><legend>${i+1}. ${axis}</legend><label class="form-label">سؤال</label><textarea name="q${i}" rows="2" class="textarea" placeholder="سؤال زاویهٔ ${i+1}">${cleanText(quiz[i]?.q||'')}</textarea><label class="form-label">کلید پاسخ کوتاه</label><input class="field" name="key${i}" value="${cleanText(quiz[i]?.answer||'')}"><label class="form-label">توضیح چرایی و چگونگی</label><textarea name="why${i}" class="textarea" rows="2">${cleanText(quiz[i]?.why||'')}</textarea></fieldset>`).join('')}</div>`}
lessonModal=function(l=null){const s=selectedSubject();if(!s)return;openModal(`<form data-form="v3-lesson-editor" data-id="${cleanText(l?.id||'')}">${modalHead(l?'ویرایش مرحلهٔ علمی':'افزودن یک پلهٔ آموزشی')}<div class="form-grid"><div class="form-full"><label class="form-label">عنوان کوچک‌ترین مفهوم مستقل *</label><input class="field" name="title" value="${cleanText(l?.title||'')}" required></div><div class="form-full"><label class="form-label">پیش‌نیاز و هدف</label><input class="field" name="goal" value="${cleanText(l?.goal||'')}"></div><div class="form-full"><label class="form-label">زمان تخمینی این پله (دقیقه)</label><input class="field" type="number" name="minutes" min="10" max="180" value="${Number(l?.minutes)||35}"></div><div class="form-full"><label class="form-label">متن آموزش بنیادی</label><textarea class="textarea" name="concept" rows="5">${cleanText(l?.concept||'')}</textarea></div><div class="form-full"><label class="form-label">شبیه‌سازی چرایی و چگونگی؛ هر خط یک وضعیت</label><textarea class="textarea" name="steps" rows="4">${cleanText(l?.steps||'')}</textarea></div><div class="form-full"><label class="form-label">مثال حل‌شده و سؤال‌وجواب مرحله‌ای</label><textarea class="textarea" name="example" rows="4">${cleanText(l?.example||'')}</textarea></div><div class="form-full"><label class="form-label">منابع؛ در هر خط یک URL</label><textarea class="textarea" name="sources" rows="2">${cleanText((l?.sources||[]).map(x=>typeof x==='string'?x:x.url).join('\n'))}</textarea></div><div class="form-full">${renderQuizEditor(l)}</div></div><div class="form-actions"><button type="submit" class="button button-primary">ذخیرهٔ درس و پنج ارزیابی</button><button type="button" data-action="close-modal" class="button button-outline">انصراف</button></div></form>`)};
function addLessonCards(s,l){const prepared=(l.cards||[]).filter(c=>c.front&&c.back).slice(0,15);const inferred=prepared.length?prepared:[{front:'«'+l.title+'» را با چرایی و چگونگی توضیح بده.',back:l.concept.slice(0,450)},{front:'برای «'+l.title+'» یک مثال واقعی بساز.',back:l.example.slice(0,450)}];let added=0;for(const c of inferred){if(state.flashcards.some(x=>x.lessonRef===l.id&&x.front===c.front))continue;state.flashcards.push({id:uid(),lessonRef:l.id,subjectRef:s.id,front:c.front,back:c.back,topic:s.title+' · '+l.title,aiAttribution:l.aiAttribution||null,box:1,dueAt:today(),createdAt:isoNow(),history:[]});added++}return added;}
function aiStudyPrompt(s,mode,l){let intro='دستور تهیهٔ برنامهٔ آموزشی مَدار. علم: '+s.title+'؛ هدف: '+(s.onboarding?.goal||s.goal)+'؛ دانش قبلی: '+(s.onboarding?.prior||'صفر')+'؛ پاسخ تعیین سطح: '+(s.onboarding?.question||'ندارد')+'؛ یادگیری ترجیحی: '+(s.onboarding?.experiments||'پویا')+'؛ منبع مطلوب: '+(s.onboarding?.sources||'دانشگاهی')+'؛ تاریخ روز را با منابع معتبر بررسی کن. تمام مفاهیم از بنیادی‌ترین پیش‌نیاز و با پله‌های کوچک و بدون پرش تا سطح هدف نقشه‌برداری شوند؛ زنجیره، وابستگی و شکاف‌ها روشن شود؛ هیچ ادعای بدون منبع را تأییدشده اعلام نکن.';
 return intro+(mode==='lesson'?'\nبرای مرحله «'+l.title+'» تدریس حسی، درونی، بنیادی، یک شبیه‌سازی چرایی و چگونگی، مثال حل‌شده، دقیقاً پنج سؤال از شناخت تا انتقال، پاسخ/توضیح و فلش‌کارت‌های کوتاه تهیه کن.':'\nابتدا یک زنجیرهٔ آغازین ۱۲ تا ۲۰ مفهوم اتمی از صفر طراحی کن. هر مرحله باید دقیقاً یک +۱ باشد؛ منابع رسمی و دانشگاهی با URL و تاریخ بیاور. برای هر مرحله پیش‌نیاز مستقیم و معیار سنجش را مشخص کن.');}
function downloadPrompt(){const s=selectedSubject();if(!s)return;const p=aiStudyPrompt(s,'plan');downloadBlob(new Blob([p],{type:'text/plain;charset=utf-8'}),'madar-plan-request-'+s.id+'.txt');showToast('دستور پژوهشی قابل استفاده در Work یا AI دیگر دریافت شد.');}
async function callLocalAI(path,payload){if(location.protocol==='file:')throw new Error('در فایل HTML آفلاین اتصال API فعال نیست. از اجرای ویندوز استفاده کن.');const profile=(state.aiProfiles||[]).find(p=>p.id===state.activeAIProfile);if(profile&&!['openai','anthropic','gemini','local'].includes(profile.brand))throw new Error('برای این ارائه‌دهنده اتصال امن سرور محلی وجود ندارد؛ ثبت نام آن به معنی اتصال نیست.');payload={...payload,providerId:({gemini:'google',local:'ollama'}[profile?.brand]||profile?.brand||'openai'),model:profile?.model||'',profileId:profile?.id||'openai'};const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});let data;try{data=await r.json()}catch{throw new Error('سرور محلی AI پاسخ JSON معتبر نداده است.')}if(!r.ok)throw new Error(data.error||'پاسخ سرور '+r.status);return data;}
async function buildPlan(){const s=selectedSubject();if(!s||planBusy)return;planBusy=true;render();try{const out=await callLocalAI('plan',{subject:s.title,onboarding:s.onboarding||onboardingDefaults(),currentTitles:(s.lessons||[]).map(l=>l.title)});const nodes=validatePlan(out);if(out._provenance?.providerId)s.planAttribution={...out._provenance,source:'api',verifiedOrigin:true};if(!nodes.length)throw new Error('مسیر معتبر یا دارای حداقل چند مرحله دریافت نشد.');if(s.lessons.some(l=>state.subjectProgress[s.id]?.includes(l.id))&&!confirm('این علم درسِ گذرانده‌شده دارد؛ می‌خواهی نقشهٔ جدید به انتهای مسیر اضافه شود تا قبولی‌ها تغییر نکنند؟'))return;
 if(s.lessons.some(l=>state.subjectProgress[s.id]?.includes(l.id))){s.lessons.push(...nodes)}else{s.lessons=nodes;state.subjectProgress[s.id]=[];state.subjectLastPlace[s.id]=nodes[0].id}
 s.planStatus=out._provenance?.webResearch===false?'offline-ai-unverified':'researched';s.planCheckedAt=isoNow();save();showToast(nodes.length+' مرحله با منبع پیشنهادی اضافه شد. لطفاً منابع و پیش‌نیازها را بررسی کن.');}catch(err){console.error(err);alert('طرح AI تولید نشد: '+err.message+'\nبرای کار آفلاین از نقشهٔ موقت یا دستور پژوهشی استفاده کن.')}finally{planBusy=false;render()}}
function validatePlan(out){if(!out||!Array.isArray(out.lessons))throw new Error('ساختار خروجی طرح درست نیست.');if(out.lessons.length>30)throw new Error('طرح بیش از ۳۰ مرحله دارد؛ برنامه را به بخش‌های کوچک تقسیم کن.');let seen=new Set();return out.lessons.map((x,i)=>{let title=String(x.title||'').trim();if(!title||title.length>160||seen.has(title))throw new Error('عنوان مرحله تکراری یا نامعتبر');seen.add(title);let urls=Array.isArray(x.sources)?x.sources.filter(z=>safeHref(typeof z==='string'?z:z?.url)).slice(0,5):[];return {id:uid(),title,minutes:clamp(Number(x.minutes)||35,10,180),goal:String(x.goal||''),concept:'',steps:'',example:'',exercise:'',expected:'',quiz:[],cards:[],sources:urls,level:i+1,verified:false,stage:'researched-outline',prerequisites:Array.isArray(x.prerequisites)?x.prerequisites.slice(0,8):[],checkedAt:isoNow()}})}
function validateLesson(content){if(!content||typeof content!=='object'||!Array.isArray(content.quiz)||content.quiz.length!==5)throw new Error('AI باید دقیقاً پنج سؤال تهیه کند.');const quiz=content.quiz.map((q,i)=>({axis:AXES[i],q:String(q.q||''),answer:String(q.answer||''),why:String(q.why||'')}));if(quiz.some(q=>!q.q||!q.answer||!q.why))throw new Error('برخی از پرسش‌ها یا کلیدها ناقص هستند.');const concept=String(content.concept||''),example=String(content.example||''),steps=Array.isArray(content.steps)?content.steps.map(String).join('\n'):String(content.steps||'');if(concept.length<120||example.length<80||steps.length<20)throw new Error('متن آموزش یا مثال به‌اندازهٔ کافی کامل نیست.');return {concept,example,steps,quiz,cards:Array.isArray(content.cards)?content.cards.filter(c=>c&&c.front&&c.back).slice(0,10):[],sources:Array.isArray(content.sources)?content.sources.filter(z=>safeHref(typeof z==='string'?z:z?.url)).slice(0,8):[],verified:false,checkedAt:isoNow(),stage:'ai-generated-unreviewed'}}
