 const trusted=uniq.length>=3;
 return {observed,activeDays:uniq.length,daysObserved:valid.length?elapsed:0,estimateRate:trusted?Math.max(.1,observed):planned,basis:trusted?'رفتار ثبت‌شده':'زمان برنامه‌ریزی‌شده'};
