const AI_PRESETS_312={
 openai:{name:'OpenAI / ChatGPT',short:'OA',site:'https://openai.com/favicon.ico',brand:'openai',model:''},
 anthropic:{name:'Anthropic / Claude',short:'C',site:'https://claude.ai/favicon.ico',brand:'anthropic',model:''},
 gemini:{name:'Google Gemini',short:'G',site:'https://gemini.google.com/favicon.ico',brand:'gemini',model:''},
 perplexity:{name:'Perplexity',short:'P',site:'https://www.perplexity.ai/favicon.ico',brand:'perplexity',model:''},
 xai:{name:'xAI / Grok',short:'X',site:'https://x.ai/favicon.ico',brand:'xai',model:''},
 local:{name:'مدل محلی آفلاین',short:'⌂',site:'',brand:'local',model:''},
 custom:{name:'هوش مصنوعی دیگر',short:'AI',site:'',brand:'custom',model:''},
};
