function ensureAIs312(){
 if(!Array.isArray(state.aiProfiles))state.aiProfiles=[];
 if(!state.aiLessonClaims||typeof state.aiLessonClaims!=='object')state.aiLessonClaims={};
 if(!state.activeAIProfile || !state.aiProfiles.some(x=>x.id===state.activeAIProfile)){
  const p=state.aiProfiles.find(x=>x.brand==='openai');state.activeAIProfile=p?.id||'';
 }
}
ensureAIs312();
titles.aiProviders=['هویت و اصالت محتوا','مدیریت هوش‌های مصنوعی'];
function logoAI312(p,small=false){
 const preset=AI_PRESETS_312[p.brand]||AI_PRESETS_312.custom;
 let src='';
 if(/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.iconData||''))src=p.iconData;
 // Remote favicons are intentionally disabled to keep learner activity private and allow strict CSP.
 // Users can upload a local icon which persists in backup.
 return `<span class="ai-logo-312 ai-brand-${cleanText(p.brand||'custom')} ${small?'ai-small-312':''}" title="${cleanText(p.name||'AI')}"><span class="ai-letters-312">${cleanText(preset.short)}</span>${src?`<img src="${cleanText(src)}" alt="" loading="lazy" >`:''}</span>`;
}
function profileAI312(id){return state.aiProfiles.find(x=>x.id===id)||null}
function aiLabel312(p){return p?`${p.name}${p.model?' · '+p.model:''}`:'منبع نامشخص'}
function effectiveLessonAttribution312(type,object){
 const s=selectedSubject(),a=activeLesson||state.lastPlace;
 const key=type==='custom'?(s&&object?'science:'+s.id+':'+object.id:''):(a?'builtin:'+a.track+':'+a.id:'');
 return {key,api:type==='custom'?object?.aiAttribution:null,manual:state.aiLessonClaims[key]||null};
}
function sourceCredit312(entry){
 if(!entry)return `<span class="ai-byline-text-312 muted">تهیه‌کنندهٔ درس ثبت نشده است؛ هیچ مدل هوش مصنوعی به آن نسبت داده نمی‌شود.</span>`;
 const p=profileAI312(entry.profileId),brand=AI_PRESETS_312[entry.providerId]||AI_PRESETS_312.custom;
 const label=p?.name||brand.name;
 const model=entry.model||p?.model||'مدل نامشخص';
 const time=entry.generatedAt?faDate(entry.generatedAt):'';
 return `<span class="ai-byline-312">${logoAI312(p||{brand:entry.providerId||'custom',name:label})}<span><strong>${cleanText(label)}</strong><span class="small muted">${cleanText(model)}${time?' · '+cleanText(time):''} · ${entry.verifiedOrigin?'پاسخ واقعی API':'انتساب اعلام‌شده توسط کاربر'}</span></span></span>`;
}
function creditPanel312(type,object){const info=effectiveLessonAttribution312(type,object);
 const origin=info.api?.verifiedOrigin?info.api:null;
 return `<section class="card ai-lesson-credit-312" style="margin-top:18px"><div class="card-title"><h3>شناسنامهٔ تولید این درس</h3>${badge(origin?'مبدأ API ثبت‌شده':info.manual?'ثبت کاربر':'نامشخص',origin?'green':'grey')}</div><div class="ai-credit-row-312">${sourceCredit312(origin)}</div>${info.manual?`<div class="ai-credit-row-312"><span class="small muted">انتساب دستی:</span>${sourceCredit312({...info.manual,verifiedOrigin:false})}</div>`:''}<p class="small muted">هویت تولیدکننده با درستی علمی محتوا فرق دارد. پاسخ‌های قبلی بدون سند به هیچ مدل خاصی منسوب نمی‌شوند.</p><button class="button button-outline button-sm" data-action="ai-credit-edit-312" data-key="${cleanText(info.key)}">${info.manual?'ویرایش انتساب دستی':'ثبت هوش مصنوعی تهیه‌کننده (دستی)'}</button></section>`;
}
function renderAI312(){ensureAIs312();const profiles=state.aiProfiles,active=profileAI312(state.activeAIProfile);
 return `<div class="intro"><div><h2>هوش‌های مصنوعی من</h2><p>AIهای مختلف را با نام، مدل و آیکون اختصاصی اضافه کن. هر درس شناسنامهٔ تولید دارد و انتساب دستی از پاسخ واقعی API قابل تشخیص است.</p></div><button class="button button-primary" data-action="ai-add-312">＋ افزودن هوش مصنوعی</button></div>
 <section class="card"><div class="card-title"><h3>انتخاب هوش مصنوعی برای تولید محتوای بعدی</h3>${badge(active?'انتخاب: '+active.name:'انتخاب نشده','grey')}</div><p class="small muted">ثبت یک نام یا آپلود لوگو به معنای اتصال به سرویس آن نیست. در این نسخه فقط OpenAI در سرور محلی ویندوز فراخوانی می‌شود؛ مدل اجراشده از پاسخ API خوانده و ثبت می‌شود.</p>
 <div class="ai-profile-grid-312">${profiles.map(p=>`<div class="ai-profile-312 ${state.activeAIProfile===p.id?'ai-selected-312':''}"><div class="ai-profile-head-312">${logoAI312(p)}<div><strong>${cleanText(p.name)}</strong><div class="small muted" dir="auto">${cleanText(p.model||'مدل تعیین نشده')}</div></div></div><div class="small muted">${p.brand==='openai'?'اتصال در سرور محلی پشتیبانی می‌شود؛ نیازمند کلید و مدل معتبر':'ثبت و انتساب فعال؛ فراخوانی مستقیم هنوز فراهم نیست'}</div><div class="ai-profile-actions-312"><button class="button button-primary button-sm" data-action="ai-select-312" data-id="${cleanText(p.id)}" ${state.activeAIProfile===p.id?'disabled':''}>${state.activeAIProfile===p.id?'انتخاب‌شده':'انتخاب'}</button><button class="button button-outline button-sm" data-action="ai-edit-312" data-id="${cleanText(p.id)}">ویرایش / آیکون</button><button class="button button-outline button-sm" data-action="ai-remove-312" data-id="${cleanText(p.id)}">حذف از فهرست</button></div></div>`).join('')||'<div class="notice">هنوز هوش مصنوعی ثبت نشده؛ از الگوهای زیر شروع کن.</div>'}</div></section>
 <section class="card"><h3>افزودن سریع از ارائه‌دهنده‌های شناخته‌شده</h3><div class="ai-preset-grid-312">${Object.entries(AI_PRESETS_312).map(([k,p])=>`<button class="ai-preset-312" data-action="ai-add-preset-312" data-brand="${k}">${logoAI312(p)}<strong>${cleanText(p.name)}</strong><span>＋ افزودن</span></button>`).join('')}</div></section>
 <section class="card"><h3>ردیابی سازندهٔ درس و فلش‌کارت</h3><p class="muted">هر درس می‌تواند با «نام ارائه‌دهنده، نام دقیق مدل، تاریخ تولید، روش ثبت و شناسهٔ پاسخ سرویس» ثبت شود. برای محتوای واردشده از سایر AIها، منبع را دستی اعلام کن؛ سیستم آن را به‌عنوان تأیید فنیِ اتصال معرفی نمی‌کند.</p><div class="notice warning">آیکون‌های پیش‌فرض برای نمایش اینترنتی از favicon وب‌سایت ارائه‌دهنده استفاده می‌کنند؛ برای نمایش مطمئن آفلاین، آیکون PNG/JPEG/WEBP خودت را بارگذاری کن. کلیدهای API را اینجا وارد نکن.</div></section>`;
}
function aiEdit312(id='',brand='custom'){
 const p=profileAI312(id),pre=AI_PRESETS_312[p?.brand||brand]||AI_PRESETS_312.custom;
 const v=p||{id:'',brand,name:pre.name,model:pre.model,iconData:''};
 openModal(`<form data-form="ai-profile-312" data-id="${cleanText(v.id)}">${modalHead(p?'ویرایش هوش مصنوعی':'افزودن هوش مصنوعی')}<div class="form-grid"><div><label class="form-label">ارائه‌دهنده</label><select class="select-field" name="brand">${Object.entries(AI_PRESETS_312).map(([k,x])=>`<option value="${k}" ${v.brand===k?'selected':''}>${cleanText(x.name)}</option>`).join('')}</select></div><div><label class="form-label">نام نمایشی *</label><input name="name" class="field" required maxlength="80" value="${cleanText(v.name)}"></div><div class="form-full"><label class="form-label">نام مدل (مثلاً شناسه مدل مورد استفاده)</label><input name="model" class="field" maxlength="96" dir="ltr" value="${cleanText(v.model||'')}" placeholder="شناسه مدل را مطابق حساب API وارد کن"></div><div class="form-full"><label class="form-label">لوگوی شخصی آفلاین (PNG/JPEG/WEBP، حداکثر ۲۵۰ کیلوبایت)</label><input class="field" type="file" name="icon" accept="image/png,image/jpeg,image/webp"><p class="small muted">با خالی‌گذاشتن فایل، آیکون قبلی حفظ می‌شود. لوگو فقط برای نمایش است.</p></div></div><div class="form-actions"><button class="button button-primary" type="submit">ذخیره AI</button><button class="button button-outline" type="button" data-action="close-modal">انصراف</button></div></form>`);
}
function creditModal312(key){const current=state.aiLessonClaims[key]||{};
 openModal(`<form data-form="ai-credit-312" data-key="${cleanText(key)}">${modalHead('انتساب دستی سازندهٔ درس')}<p class="small muted">فقط وقتی واقعاً می‌دانی این درس توسط چه AI و مدلی نوشته شده، آن را ثبت کن. این انتساب گواهی فنی API نیست.</p><div class="form-grid"><div class="form-full"><label class="form-label">AI تهیه‌کننده</label><select name="profileId" class="select-field" required><option value="">انتخاب کن...</option>${state.aiProfiles.map(p=>`<option value="${cleanText(p.id)}" ${current.profileId===p.id?'selected':''}>${cleanText(aiLabel312(p))}</option>`).join('')}</select></div><div class="form-full"><label class="form-label">نام دقیق مدل در زمان تولید</label><input name="model" class="field" dir="ltr" maxlength="96" value="${cleanText(current.model||'')}"></div><div class="form-full"><label class="form-label">یادداشت دربارهٔ منبع و چگونگی تهیه</label><textarea class="textarea" name="notes" rows="2" maxlength="500">${cleanText(current.notes||'')}</textarea></div></div><div class="form-actions"><button class="button button-primary" type="submit">ثبت انتساب دستی</button>${current.profileId?'<button class="button button-outline" type="button" data-action="ai-credit-clear-312" data-key="'+cleanText(key)+'">پاک‌کردن انتساب دستی</button>':''}<button class="button button-outline" type="button" data-action="close-modal">انصراف</button></div></form>`);
}
const renderBeforeAI312=render;
render=function(){ensureAIs312();if(view==='aiProviders'){
 document.querySelector('#page-eyebrow').textContent='مدیریت مدل‌ها';document.querySelector('#page-title').textContent='هوش‌های مصنوعی من';
 document.querySelector('#today-date').textContent=faDate(new Date(),{weekday:'long',day:'numeric',month:'long'});
 document.querySelector('#page-root').innerHTML=renderAI312();
 document.querySelector('#sidebar')?.classList.remove('open');
 document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.nav==='aiProviders'));
 return;
 }
 renderBeforeAI312();
 const root=document.querySelector('#page-root');if(!root)return;
 if(view==='subjectLesson'&&activeCustomLesson())root.insertAdjacentHTML('beforeend',creditPanel312('custom',activeCustomLesson()));
 if(view==='lesson'&&activeLesson)root.insertAdjacentHTML('beforeend',creditPanel312('builtin',null));
 if(view==='review'){
  const c=state.flashcards.find(x=>x.id===currentReviewId)||(dueCards()[0]||null);
  if(c){const byline=c.aiAttribution?sourceCredit312(c.aiAttribution):'<span class="small muted">منشأ ساخت این کارت ثبت نشده است.</span>';
   root.insertAdjacentHTML('beforeend',`<section class="card ai-lesson-credit-312" style="margin-top:18px"><h3>منشأ کارت در حال نمایش</h3>${byline}</section>`);
  }
 }
};
const aiNav312=document.createElement('button');aiNav312.type='button';aiNav312.className='nav-item';aiNav312.dataset.nav='aiProviders';aiNav312.innerHTML='<span class="nav-ico">◈</span> مدیریت هوش‌های مصنوعی';
document.querySelector('.side-nav [data-nav="advisor"]')?.insertAdjacentElement('afterend',aiNav312);
// Prevent invalid attribution by always storing manual declarations separately from API proof.
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='ai-add-312'){aiEdit312();return}
 if(a==='ai-add-preset-312'){aiEdit312('',el.dataset.brand||'custom');return}
 if(a==='ai-edit-312'){aiEdit312(el.dataset.id);return}
 if(a==='ai-select-312'){state.activeAIProfile=el.dataset.id;save();render();showToast('AI پیش‌فرض انتخاب شد؛ اتصال فقط برای ارائه‌دهنده‌های پشتیبانی‌شده فعال است.');return}
 if(a==='ai-remove-312'){const p=profileAI312(el.dataset.id);if(!p)return;if(!confirm('فقط این AI از فهرست حذف شود؟ انتساب‌های ثبت‌شدهٔ قبلی باقی می‌مانند اما آیکون سفارشی آن ممکن است از دست برود.'))return;state.aiProfiles=state.aiProfiles.filter(x=>x.id!==p.id);ensureAIs312();save();render();return}
 if(a==='ai-credit-edit-312'){creditModal312(el.dataset.key);return}
 if(a==='ai-credit-clear-312'){delete state.aiLessonClaims[el.dataset.key];save();closeModal();render();showToast('انتساب دستی پاک شد؛ منشأ ثبت‌شده توسط API دست‌نخورده باقی ماند.');return}
},true);
document.addEventListener('submit',async e=>{
 const form=e.target.closest('form[data-form]');if(!form||!['ai-profile-312','ai-credit-312'].includes(form.dataset.form))return;
 e.preventDefault();e.stopImmediatePropagation();
 const fd=new FormData(form);
 if(form.dataset.form==='ai-credit-312'){
  const id=String(fd.get('profileId')||'');const p=profileAI312(id);if(!p){showToast('یک AI ثبت‌شده انتخاب کن.');return}
  const model=String(fd.get('model')||p.model||'').trim();state.aiLessonClaims[form.dataset.key]={profileId:id,providerId:p.brand,model,notes:String(fd.get('notes')||'').trim(),generatedAt:isoNow(),source:'manual',verifiedOrigin:false};save();closeModal();render();showToast('انتساب دستی با برچسب «اعلام کاربر» ثبت شد.');return;
 }
 const file=fd.get('icon'),name=String(fd.get('name')||'').trim(),brand=String(fd.get('brand')||'custom'),model=String(fd.get('model')||'').trim();
 if(!name||!AI_PRESETS_312[brand]){showToast('نام و ارائه‌دهندهٔ معتبر لازم است.');return}
 if(model&&!/^[A-Za-z0-9._:\/-]{1,96}$/.test(model)){showToast('نام مدل فقط حروف انگلیسی، عدد و نشانه‌های شناخته‌شده داشته باشد.');return}
 let img='';if(file instanceof File&&file.size>0){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>250*1024){showToast('آیکون باید PNG/JPEG/WEBP و کمتر از ۲۵۰ کیلوبایت باشد.');return}
  img=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=()=>rej(new Error('خواندن تصویر ممکن نشد'));reader.readAsDataURL(file)});
 }
 const p=profileAI312(form.dataset.id);if(p){p.name=name;p.brand=brand;p.model=model;if(img)p.iconData=img}
 else{const id='aip-'+uid();state.aiProfiles.push({id,brand,name,model,iconData:img,createdAt:isoNow()});if(!state.activeAIProfile)state.activeAIProfile=id}
 save();closeModal();render();showToast('هوش مصنوعی و آیکون آن در فضای کار ذخیره شد.');
},true);


